    msteps SEGS (mkst regs (0x7a0fc : word) m rom) (mkst regs' (0x7a1bc : word) m rom)
    /\ getr regs' 13 = Z_to_bv 64 swpl /\ getr regs' 22 = Z_to_bv 64 datas /\ getr regs' 21 = Z_to_bv 64 2
