(* [comment removed for export] *)
Lemma rl3_T : forall regs m (srow drow n4 k : Z),
  (0 <= k < 32)%Z ->
  getr regs 31 = Z_to_bv 64 srow -> getr regs 8 = Z_to_bv 64 drow -> getr regs 18 = Z_to_bv 64 n4 -> getr regs 15 = Z_to_bv 64 k ->
  exists regs',
    msteps SEGS (mkst regs (0x7a8d4 : word) m rom) (mkst regs' (if Z.eq_dec k 0 then (0x7a89c : word) else (0x7a880 : word)) m rom)
    /\ getr regs' 9 = Z_to_bv 64 (drow + n4) /\ getr regs' 18 = Z_to_bv 64 (srow + n4)
    /\ regs_agree (fun r => In r [9; 18]%list) regs regs'.
Proof.
